export default App;

import { GoogleGenAI } from "@google/genai";

export interface GenerationParams {
  sourceImage: string;
  styleName: string;
  styleDescription: string;
}

export interface EditParams {
  sourceImage: string;
  prompt: string;
}

export interface NewImageParams {
  prompt: string;
  imageSize: "1K" | "2K" | "4K";
}

export const analyzeImage = async (sourceImage: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: "Perform a deep, complex professional analysis of this fashion portrait. Discuss lighting, composition, mood, wardrobe, and specific editorial qualities. Provide high-level creative insights. Be thorough and critical as a world-class fashion editor.",
        },
      ],
    },
    config: {
      thinkingConfig: {
        thinkingBudget: 32768
      }
    }
  });

  return response.text || "Analysis unavailable.";
};

export const generateFashionPortrait = async ({ sourceImage, styleName, styleDescription }: GenerationParams) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  let transformationType = "high-end fashion enhancement";
  if (styleName === "Ghibli" || styleName === "Anime") {
    transformationType = "artistic illustration transformation";
  } else if (styleName === "BG Remove") {
    transformationType = "subject isolation and cleanup";
  }

  const promptText = `Act as a world-class AI visual artist. 
  Task: Perform a ${transformationType} on the person in the attached image.

  Requested Style: ${styleName}
  Style Guidelines: ${styleDescription}

  Strict Requirements:
  - Preserve the subject's fundamental identity: facial features, bone structure, hairstyle, facial hair (beard/stubble), and distinctive eye characteristics MUST remain recognizable.
  - The model's likeness is paramount; do not genericize the face.
  - If it's an artistic style (Ghibli/Anime), translate these specific features into that art style accurately.
  - If it's a fashion style, apply the wardrobe and lighting seamlessly while maintaining the original face.
  - Lighting: Cinematic, professional, and consistent with a high-end fashion editorial.
  - Resolution: Ultra-high detail, 8k quality aesthetic.
  - Output: A single high-fidelity image.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: promptText,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "3:4"
      }
    }
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  throw new Error("Generation failed: The AI did not return a valid image.");
};

export const editImageWithPrompt = async ({ sourceImage, prompt }: EditParams) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: `Modify this image based on the following instruction: ${prompt}. Maintain the original quality and context where possible while applying the changes accurately. Ensure facial identity (eyes, nose, hairstyle, facial hair) is preserved.`,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "3:4"
      }
    }
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  throw new Error("Editing failed: The AI did not return a valid image.");
};

export const generateNewImage = async ({ prompt, imageSize }: NewImageParams) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        {
          text: `Create a cinematic, high-fashion editorial image: ${prompt}. Ensure high detail, professional lighting, and magazine-quality composition.`,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "3:4",
        imageSize: imageSize
      },
    },
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  throw new Error("Creation failed: The AI did not return a valid image.");
};

