export const generateFashionPortrait = async ({ sourceImage, styleName, styleDescription, aspectRatio = "3:4" }: GenerationParams) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  let transformationType = "high-end fashion enhancement";
  let specificRules = "";

  if (styleName === "Ultra Enhance") {
    transformationType = "lossless neural restoration and clarity recovery";
    specificRules = `
    - ZERO identity drift. The person must be 100% recognizable.
    - Recover micro-textures: skin pores, fabric weaves, and individual hair strands.
    - Remove all compression artifacts, blur, and noise.
    - DO NOT add any artistic filters or color changes.
    - Enhance sharpness and lighting for a crystal-clear, high-definition result.`;
  } else if (styleName === "Studio Polish") {
    transformationType = "high-end editorial studio retouching";
    specificRules = `
    - Act as a senior magazine retoucher.
    - Smooth skin while preserving realistic texture (no plastic look).
    - Perfect the lighting: add subtle rim light, soft key light, and balance shadows for a professional look.
    - Sharpen the eyes and refine the hair for maximum clarity.
    - Maintain 100% accurate facial identity and features.`;
  } else if (styleName === "Ghibli" || styleName === "Anime") {
    transformationType = "artistic illustration transformation";
  } else if (styleName === "BG Remove") {
    transformationType = "subject isolation and cleanup";
  }

  const promptText = `Act as a world-class AI visual artist and professional photo retoucher. 
  Task: Perform a ${transformationType} on the person in the attached image.

  Requested Style: ${styleName}
  Style Guidelines: ${styleDescription}

  Strict Requirements:
  ${specificRules}
  - Preserve the subject's fundamental identity: facial features, bone structure, hairstyle, facial hair (beard/stubble), and distinctive eye characteristics MUST remain identical to the original.
  - The model's likeness is the most important factor.
  - Lighting: Cinematic, professional, and consistent with a high-end fashion editorial.
  - Resolution: Ultra-high detail, 8k quality aesthetic.
  - Output: A single high-fidelity image that looks like it was shot on a professional cinema camera.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: promptText,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    }
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  throw new Error("Generation failed: The AI did not return a valid image.");
};

