type AppTab = 'enhance' | 'create';
type ImageResolution = '1K' | '2K' | '4K';

const REFINEMENTS = [
  { label: "Ultra Enhance", prompt: "Perfectly restore and enhance the image quality. Sharpen features, remove noise, and bring out realistic textures without changing the style." },
  { label: "Studio Polish", prompt: "Apply professional magazine-grade studio retouching. Perfect skin tones, optimize lighting, and sharpen eyes for a high-end look." },
