                    <button 
                      onClick={handleFullReset}
                      className="w-full py-4 text-[9px] uppercase tracking-[0.4em] text-zinc-600 hover:text-zinc-300 font-bold border border-zinc-900 rounded-2xl transition-all"
                    >
                      Reset Studio Session
