import { GoogleGenAI } from "@google/genai";

export type AspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export interface FineTuneParams {
  lighting: number;
  temperature: number;
}

export interface GenerationParams {
  sourceImage: string;
  styleName: string;
  styleDescription: string;
  aspectRatio?: AspectRatio;
  fineTune?: FineTuneParams;
}

export interface EditParams {
  sourceImage: string;
  prompt: string;
  aspectRatio?: AspectRatio;
}

export interface NewImageParams {
  prompt: string;
  imageSize: "1K" | "2K" | "4K";
  aspectRatio?: AspectRatio;
}

export const analyzeImage = async (sourceImage: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: "Perform a deep, complex professional analysis of this fashion portrait. Discuss lighting, composition, mood, wardrobe, and specific editorial qualities. Provide high-level creative insights. Be thorough and critical as a world-class fashion editor.",
        },
      ],
    },
    config: {
      thinkingConfig: {
        thinkingBudget: 32768
      }
    }
  });

  return response.text || "Analysis unavailable.";
};

export const generateFashionPortrait = async ({ 
  sourceImage, 
  styleName, 
  styleDescription, 
  aspectRatio = "3:4",
  fineTune 
}: GenerationParams) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = sourceImage.split(',')[1];
  const mimeType = sourceImage.split(',')[0].split(':')[1].split(';')[0];

  let transformationType = "high-end fashion enhancement";
  let specificRules = "";

  if (styleName === "Ultra Enhance") {
    transformationType = "lossless neural restoration and clarity recovery";
    specificRules = `
    - ZERO identity drift. The person must be 100% recognizable.
    - Recover micro-textures: skin pores, fabric weaves, and individual hair strands.
    - Remove all compression artifacts, blur, and noise.
    - DO NOT add any artistic filters or color changes.
    - Enhance sharpness and lighting for a crystal-clear, high-definition result.`;
  } else if (styleName === "Studio Polish") {
    transformationType = "high-end editorial studio retouching";
    specificRules = `
    - Act as a senior magazine retoucher.
    - Smooth skin while preserving realistic texture (no plastic look).
    - Perfect the lighting: add subtle rim light, soft key light, and balance shadows for a professional look.
    - Sharpen the eyes and refine the hair for maximum clarity.
    - Maintain 100% accurate facial identity and features.`;
  }

  // Handle fine-tuning logic
  let tuningInstructions = "";
  if (fineTune) {
    const { lighting, temperature } = fineTune;

    if (lighting < 30) {
      tuningInstructions += "- Lighting: Deeply moody, low-key, heavy shadows, high dramatic contrast.\n";
    } else if (lighting > 70) {
      tuningInstructions += "- Lighting: Bright, high-key, clean studio fill lighting, minimal shadows.\n";
    }

    if (temperature < 30) {
      tuningInstructions += "- Color Temperature: Cool arctic tones, icy blues and teals, stark cinematic mood.\n";
    } else if (temperature > 70) {
      tuningInstructions += "- Color Temperature: Warm golden hour glow, sunset oranges and rich ambers, nostalgic heat.\n";
    } else if (temperature >= 40 && temperature <= 60) {
      tuningInstructions += "- Color Temperature: Perfect neutral color balance, accurate daylight white balance.\n";
    }
  }

  const promptText = `Act as a world-class AI visual artist and professional photo retoucher. 
  Task: Perform a ${transformationType} on the person in the attached image.

  Requested Style: ${styleName}
  Style Guidelines: ${styleDescription}

  ${tuningInstructions ? `Fine-Tuning Adjustments:\n${tuningInstructions}` : ''}

  Strict Identity Preservation Rules:
  - PROTECT FACE FEATURES: The eyes, nose, mouth shape, and bone structure must remain exactly as they appear in the source.
  - PROTECT HAIR & BEARD: Maintain the exact hairstyle, hair texture, and facial hair (beard/stubble/mustache) style and grooming.
  - No "beautification" that alters underlying anatomy.
  - The model's likeness is the paramount priority.

  Editorial Aesthetic:
  ${specificRules}
  - Lighting: Cinematic, professional, and consistent with a high-end fashion editorial.
  - Resolution: Ultra-high detail, 8k quality aesthetic.
  - Output: A single high-fidelity image that looks like it was shot on a professional Hasselblad camera.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: promptText,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    }
  });

  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  throw new Error("Generation failed: The AI did not return a valid image.");
};

